/**
 * Test flow for associateRecordToEmail action
 * Demonstrates associating a record with an email
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testAssociateRecordToEmail = Flow(
    {
        $id: Now.ID['test_associate_record_to_email_flow'],
        name: 'Test Associate Record To Email',
        description: 'Tests the associateRecordToEmail core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_associate_record_to_email_trigger'] },
        {
            table: 'sys_email',
            condition: 'type=received',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        // Create an incident first
        const incident = wfa.action(
            action.core.createRecord,
            { $id: Now.ID['test_associate_create_incident'] },
            {
                table_name: 'incident',
                values: TemplateValue({
                    short_description: 'Test Incident',
                    priority: 3,
                }),
            }
        )

        wfa.action(
            action.core.associateRecordToEmail,
            { $id: Now.ID['test_associate_record_to_email_action'] },
            {
                email_record: wfa.dataPill(_params.trigger.current.sys_id, 'reference'),
                target_record: wfa.dataPill(incident.record, 'reference'),
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_associate_record_to_email_log'] },
            {
                log_level: 'info',
                log_message: `associateRecordToEmail outputs: email_record=${wfa.dataPill(_params.trigger.current.sys_id, 'reference')}`,
            }
        )
    }
)
